// ==UserScript==
// @name         Zeta Cosmetics Loader
// @namespace    zeta
// @version      0.1.9
// @author       Zeta (numbers, juju)
// @description  Custom cosmetics loader for buildnow.gg
// @match        *://*.crazygames.com/*
// @match        *://crazygames.com/*
// @run-at       document-start
// @grant        GM_xmlhttpRequest
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_registerMenuCommand

// @icon           data:image/jpeg;base64,
// @updateURL    https://rtdsvvwowdahdzpnlvtq.supabase.co/storage/v1/object/public/cdn/zetascript.user.js
// @downloadURL  https://rtdsvvwowdahdzpnlvtq.supabase.co/storage/v1/object/public/cdn/zetascript.user.js
// @connect      *
// ==/UserScript==
(function () {
  'use strict';

  const W = (typeof unsafeWindow !== 'undefined' && unsafeWindow) ? unsafeWindow : window;

  // ------------------------------------------------------------------ asset server
  const DEFAULT_BASE = 'https://zeta-project.onrender.com';
  const SCRIPT_VERSION = '0.1.12';

  function normalizeBase(v) {
    if (typeof v !== 'string') return null;
    let s = v.trim();
    if (!s) return null;
    if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) s = 'http://' + s;
    if (!/^https?:\/\//i.test(s)) return null;
    s = s.replace(/\/+$/, '');
    if (!/^https?:\/\/[^\s]+$/i.test(s)) return null;
    const host = s.replace(/^https?:\/\//i, '').split('/')[0];
    return /^[a-z0-9._-]+(:\d{1,5})?$/i.test(host) ? s : null;
  }

  function savedBase() {
    try {
      if (typeof GM_getValue === 'function') {
        const v = normalizeBase(GM_getValue('base', ''));
        if (v) return v;
      }
    } catch (e) {}
    return DEFAULT_BASE;
  }

  function savedLicenseKey() {
    try {
      return typeof GM_getValue === 'function'
        ? String(GM_getValue('licenseKey', '') || '').trim()
        : '';
    } catch (e) {
      return '';
    }
  }

  function savedClientId() {
    try {
      const stored = typeof GM_getValue === 'function'
        ? String(GM_getValue('clientId', '') || '')
        : '';
      if (/^[a-f0-9]{64}$/.test(stored)) return stored;
      const cryptoApi = W.crypto || (typeof crypto !== 'undefined' ? crypto : null);
      if (!cryptoApi || typeof cryptoApi.getRandomValues !== 'function') {
        throw new Error('Secure random generation is unavailable.');
      }
      const bytes = new Uint8Array(32);
      cryptoApi.getRandomValues(bytes);
      const clientId = Array.prototype.map.call(bytes, function (byte) {
        return byte.toString(16).padStart(2, '0');
      }).join('');
      if (typeof GM_setValue !== 'function') {
        throw new Error('Userscript storage is unavailable.');
      }
      GM_setValue('clientId', clientId);
      return clientId;
    } catch (error) {
      throw new Error('Could not initialize this userscript installation: ' +
        String(error && error.message || error));
    }
  }

  const LOCAL       = savedBase();
  const SS_ROOT     = '/buildnow-gg/225/Build/StreamingAssets';
  const AA_PATH     = SS_ROOT + '/aa';
  const LOCAL_AA    = LOCAL + '/files/game' + SS_ROOT + '/aa';
  const GAME_CDN_AA = 'https://files.crazygames.com' + AA_PATH;
  const IS_GAME_FRAME = (function () {
    try {
      return /(^|\.)buildnow-gg\.game-files\.crazygames\.com$/i.test(String(location.host || '')) &&
        String(location.pathname || '').indexOf('/unity/unity2020/') === 0;
    } catch (e) { return false; }
  })();
  const RT_TOKEN   = '{UnityEngine.AddressableAssets.Addressables.RuntimePath}';
  const STAMP      = 'bngv=' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  const GM_OK      = (typeof GM_xmlhttpRequest !== 'undefined');

  const stats = {
    armed: location.href,
    gm: GM_OK,
    configHooked: false,
    prefetch: { settings: 0, catalog: 0, bundles: 0, errors: [] },
    rewrites: 0,
    misses: []
  };
  W.__sw = stats;

  const T0 = Date.now();
  let _loadGame = null;
  let _create = null;
  let reportsSent = 0;

  const blobByPath = new Map();
  let prefetchPromise = null;
  let assetsReady = false;
  let prefetchState = 'loading';
  let clientLeaseStatus = 'active';
  let leaseHeartbeatTimer = null;
  let origSS = null;
  let apiScope = null;
  let apiCosmetics = null;

  function log() {
    try { console.log.apply(console, ['[bng-swap]'].concat([].slice.call(arguments))); } catch (e) {}
  }

  function report(tag, extra) {
    try {
      if (!GM_OK || reportsSent > 60) return;
      reportsSent++;
      const payload = Object.assign({
        f: (location.host.indexOf('game-files') >= 0 ? 'GAME'
            : location.host.indexOf('games.') === 0 ? 'MID' : 'TOP'),
        ms: Date.now() - T0,
        cfg: stats.configHooked ? 1 : 0,
        rew: stats.rewrites
      }, extra || {});
      GM_xmlhttpRequest({
        method: 'GET',
        url: LOCAL + '/__beacon?tag=' + encodeURIComponent('STAT ' + tag + ' ' + JSON.stringify(payload)),
        timeout: 4000
      });
    } catch (e) {}
  }

  // ------------------------------------------------------------------ settings menu
  function ui(msg, def) {
    try { return (W.prompt || prompt).call(W, msg, def); } catch (e) { return null; }
  }

  function say(msg) {
    try { (W.alert || alert).call(W, msg); } catch (e) {}
  }

  try {
    if (typeof GM_registerMenuCommand === 'function') {
      GM_registerMenuCommand('Set Zeta API URL', function () {
        const v = ui('Zeta API URL\n\nCurrently using: ' + LOCAL, LOCAL);
        if (v === null) return;
        if (!v.trim()) {
          try { GM_setValue('base', ''); } catch (e) {}
          say('Cleared. Reload to use ' + DEFAULT_BASE);
          return;
        }
        const n = normalizeBase(v);
        if (!n) { say('That does not look like a URL.'); return; }
        try { GM_setValue('base', n); } catch (e) {}
        say('Saved: ' + n + '\nReload the game page to use it.');
      });
    }
  } catch (e) {}

  // ------------------------------------------------------------------ License Modal
  let keyModalPromise = null;
  function openLicenseKeyModal(message) {
    if (keyModalPromise) return keyModalPromise;
    keyModalPromise = new Promise(function (resolve) {
      const d = W.document;
      function mount() {
        if (!d.body) {
          if (d.readyState === 'loading') {
            d.addEventListener('DOMContentLoaded', mount, { once: true });
          } else {
            W.setTimeout(mount, 50); // Fallback polling if DOMContentLoaded already fired
          }
          return;
        }

        const previous = d.getElementById('bng-license-modal');
        if (previous) previous.remove();

        const style = d.createElement('style');
        style.id = 'bng-license-modal-style';
        style.textContent =
          '#bng-license-modal{position:fixed;inset:0;z-index:2147483647;display:grid;place-items:center;overflow:hidden;padding:16px;background:rgba(0,0,0,.72);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif;color:#f5f5f5}' +
          '#bng-license-modal .bng-card{box-sizing:border-box;width:min(400px,calc(100vw - 32px));padding:24px;border:1px solid #303030;border-radius:18px;background:#141414;box-shadow:0 24px 80px rgba(0,0,0,.55)}' +
          '#bng-license-modal .bng-title{margin:0 0 8px;color:#fff;font-size:19px;font-weight:650;letter-spacing:-.03em}' +
          '#bng-license-modal .bng-note{margin:0 0 18px;color:#aaa;font-size:13px}' +
          '#bng-license-modal .bng-input{box-sizing:border-box;width:100%;height:44px;padding:0 13px;border:1px solid #3c3c3c;border-radius:10px;outline:none;background:#0b0b0b;color:#fff;font:inherit}' +
          '#bng-license-modal .bng-input::placeholder{color:#777}' +
          '#bng-license-modal .bng-input:focus{border-color:#aaa;box-shadow:0 0 0 3px rgba(255,255,255,.08)}' +
          '#bng-license-modal .bng-status{min-height:20px;margin-top:10px;color:#bdbdbd;font-size:12px}' +
          '#bng-license-modal .bng-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}' +
          '#bng-license-modal button{height:38px;padding:0 14px;border:1px solid #f5f5f5;border-radius:10px;background:#f5f5f5;color:#111;font:600 13px system-ui,-apple-system,"Segoe UI",sans-serif;cursor:pointer}' +
          '#bng-license-modal button:hover:not(:disabled){background:#dcdcdc}' +
          '#bng-license-modal button:disabled{border-color:#454545;background:#303030;color:#888;cursor:wait}' +
          '#bng-license-modal .bng-secondary{border-color:#414141;background:#1c1c1c;color:#eee}' +
          '#bng-license-modal .bng-secondary:hover{background:#292929}';
        if (!d.getElementById('bng-license-modal-style')) d.head.appendChild(style);

        const overlay = d.createElement('div');
        overlay.id = 'bng-license-modal';
        const card = d.createElement('section');
        card.className = 'bng-card';

        const title = d.createElement('h2');
        title.className = 'bng-title';
        title.textContent = 'Connect your license';
        const note = d.createElement('p');
        note.className = 'bng-note';
        note.textContent = 'Enter your Zeta key to load assets.';
        const input = d.createElement('input');
        input.className = 'bng-input';
        input.type = 'password';
        input.placeholder = 'ZETA-…';
        input.value = savedLicenseKey();
        input.autocomplete = 'off';
        input.autocapitalize = 'off';
        input.spellcheck = false;
        input.setAttribute('aria-label', 'Zeta license key');

        const status = d.createElement('div');
        status.className = 'bng-status';
        status.setAttribute('role', 'status');
        status.setAttribute('aria-live', 'polite');
        status.textContent = message || '';

        const actions = d.createElement('div');
        actions.className = 'bng-actions';
        const closeButton = d.createElement('button');
        closeButton.className = 'bng-secondary';
        closeButton.textContent = 'Continue with stock';
        const saveButton = d.createElement('button');
        saveButton.textContent = 'Validate key';
        saveButton.disabled = !input.value.trim();

        let settled = false;
        let keyValidated = false;
        function finish(value) {
          if (settled) return;
          settled = true;
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
          keyModalPromise = null;
          resolve(value);
        }

        saveButton.onclick = function () {
          const key = input.value.trim();
          if (!key || saveButton.disabled) return;
          saveButton.disabled = true;
          status.textContent = 'Checking your key with the Zeta API…';
          validateLicenseKey(key).then(function () {
            if (typeof GM_setValue !== 'function') {
              throw new Error('Userscript storage is unavailable.');
            }
            GM_setValue('licenseKey', key);
            keyValidated = true;
            saveButton.textContent = 'Validated';
            status.textContent = 'Key valid. Press Ctrl+R or F5 to reload and load your cosmetics.';
            closeButton.textContent = 'Close';
          }).catch(function (error) {
            status.textContent = String(error && error.message || error);
            saveButton.disabled = false;
            saveButton.textContent = 'Validate key';
          });
        };
        closeButton.onclick = function () { finish(''); };
        input.addEventListener('input', function () {
          if (keyValidated) return;
          saveButton.disabled = !input.value.trim();
          status.textContent = '';
        });
        input.onkeydown = function (e) {
          if (e.key === 'Enter') { e.preventDefault(); saveButton.click(); }
          if (e.key === 'Escape') finish('');
        };

        actions.appendChild(closeButton);
        actions.appendChild(saveButton);
        card.appendChild(title);
        card.appendChild(note);
        card.appendChild(input);
        card.appendChild(status);
        card.appendChild(actions);
        overlay.appendChild(card);
        d.body.appendChild(overlay);
        input.focus();
      }
      mount();
    });
    return keyModalPromise;
  }

  // ------------------------------------------------------------------ helpers
  function apiHeaders(url) {
    if (typeof url !== 'string' ||
        (url.indexOf(LOCAL + '/files/') !== 0 && url.indexOf(LOCAL + '/cosmetics') !== 0)) {
      return {};
    }
    const key = savedLicenseKey();
    if (!key) return {};
    const headers = { 'X-Zeta-Key': key, 'X-Zeta-Client': savedClientId() };
    if (url.indexOf(LOCAL + '/files/') === 0) {
      headers['X-Zeta-Download-Mode'] = 'redirect-v1';
    }
    return headers;
  }

  function validateLicenseKey(key) {
    return new Promise(function (resolve, reject) {
      if (!GM_OK) {
        reject(new Error('Userscript request permission is unavailable.'));
        return;
      }
      try {
        GM_xmlhttpRequest({
          method: 'POST',
          url: LOCAL + '/validate',
          headers: {
            'Content-Type': 'application/json',
            'X-Zeta-Client': savedClientId()
          },
          data: JSON.stringify({ key: key }),
          timeout: 15000,
          responseType: 'json',
          onload: function (response) {
            if (response.status === 401) {
              reject(new Error('Key not valid. Check it and try again.'));
              return;
            }
            if (response.status === 409) {
              reject(new Error('This key is active in another client. Retry after five minutes idle.'));
              return;
            }
            if (response.status === 429) {
              reject(new Error('Too many validation attempts. Please wait and try again.'));
              return;
            }
            if (response.status < 200 || response.status >= 300) {
              let detail = '';
              try {
                let body = response.response;
                if (typeof body === 'string') body = JSON.parse(body);
                if (body && Array.isArray(body.detail)) {
                  detail = body.detail.map(function (item) {
                    const location = Array.isArray(item.loc) ? item.loc.join('.') : '';
                    return (location ? location + ': ' : '') + (item.msg || 'Invalid input');
                  }).join('; ');
                } else if (body && typeof body.detail === 'string') {
                  detail = body.detail;
                }
              } catch (error) {
                detail = 'The API returned an unreadable error response';
              }
              reject(new Error(
                'The Zeta API could not validate this key (HTTP ' + response.status + ')' +
                (detail ? ': ' + detail : '.')
              ));
              return;
            }
            let result = response.response;
            if (typeof result === 'string') {
              try { result = JSON.parse(result); }
              catch (error) {
                reject(new Error('The Zeta API returned an unreadable validation response.'));
                return;
              }
            }
            if (!result || result.valid !== true) {
              reject(new Error('The Zeta API did not confirm this key.'));
              return;
            }
            resolve(result);
          },
          onerror: function () { reject(new Error('Could not reach the Zeta API. Check your connection.')); },
          ontimeout: function () { reject(new Error('Key validation timed out. Please try again.')); }
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  function gmGet(url, timeoutMs) {
    function responseHeader(response, name) {
      const pattern = new RegExp('^' + name + ':\\s*([^\\r\\n]+)', 'im');
      const match = String(response.responseHeaders || '').match(pattern);
      return match ? match[1].trim() : '';
    }

    function request(requestUrl, headers, allowAssetRedirect) {
      return new Promise(function (resolve, reject) {
        if (!GM_OK) { reject(new Error('GM_xmlhttpRequest unavailable')); return; }
        try {
          GM_xmlhttpRequest({
            method: 'GET',
            url: requestUrl,
            headers: headers || apiHeaders(requestUrl),
            timeout: timeoutMs || 30000,
            responseType: 'arraybuffer',
            onload: function (r) {
              if (r.status >= 200 && r.status < 300) {
                const contentType = responseHeader(r, 'content-type').toLowerCase();
                const isAssetRedirect =
                  contentType.indexOf('application/vnd.zeta.asset-redirect+json') === 0 ||
                  responseHeader(r, 'x-zeta-asset-redirect') === '1';
                if (isAssetRedirect) {
                  if (!allowAssetRedirect) {
                    reject(new Error('The asset service returned a nested download redirect.'));
                    return;
                  }
                  try {
                    const decoder = W.TextDecoder || TextDecoder;
                    const pointerText = typeof r.response === 'string'
                      ? r.response
                      : new decoder('utf-8').decode(new Uint8Array(r.response));
                    const pointer = JSON.parse(pointerText);
                    const DownloadURL = W.URL || URL;
                    const target = new DownloadURL(pointer.download_url);
                    if (target.protocol !== 'https:' ||
                        !target.hostname.endsWith('.githubusercontent.com') ||
                        target.username || target.password || target.hash) {
                      throw new Error('The asset service returned an untrusted download host.');
                    }
                    request(target.href, {}, false).then(resolve, reject);
                  } catch (error) {
                    reject(error);
                  }
                  return;
                }
                resolve(r);
              }
              else if (r.status === 401) {
                const error = new Error('HTTP 401: key not accepted.');
                error.status = 401;
                error.authenticatedAssetRequest = requestUrl.indexOf(LOCAL + '/files/') === 0;
                reject(error);
              } else reject(new Error('HTTP ' + r.status + ' for ' +
                (allowAssetRedirect ? requestUrl : 'authorized asset download')));
            },
            onerror: function () {
              reject(new Error('network error for ' +
                (allowAssetRedirect ? requestUrl : 'authorized asset download')));
            },
            ontimeout: function () {
              reject(new Error('timeout for ' +
                (allowAssetRedirect ? requestUrl : 'authorized asset download')));
            }
          });
        } catch (e) { reject(e); }
      });
    }
    function promptAndRetry(error) {
      if (!IS_GAME_FRAME || error.status !== 401 || !error.authenticatedAssetRequest) throw error;
      return openLicenseKeyModal('That key was not accepted. Enter a valid key, or continue with stock assets.').then(function (key) {
        if (!key) throw error;
        return request(url, null, true);
      });
    }
    return request(url, null, true).catch(promptAndRetry);
  }

  function makeBlobUrl(buf, mime) {
    const BlobCtor = W.Blob || Blob;
    const URLCtor  = W.URL || URL;
    return URLCtor.createObjectURL(new BlobCtor([buf], { type: mime || 'application/octet-stream' }));
  }

  function aaKey(u) {
    if (!u || typeof u !== 'string' || u.indexOf('blob:') === 0) return null;
    try {
      const p = new W.URL(u, location.href).pathname;
      const i = p.lastIndexOf('/aa/');
      if (i < 0) return null;
      return p.slice(i + 4).replace(/^\/+/, '');
    } catch (e) { return null; }
  }

  function register(rel, blobUrl) {
    const k = String(rel == null ? '' : rel).replace(/^\/+/, '');
    if (k && blobUrl) blobByPath.set(k, blobUrl);
  }

  function blobFor(u) {
    const k = aaKey(u);
    return k ? (blobByPath.get(k) || null) : null;
  }

  const DATA_HASH = 'cdbbb83c0ef9757d51e8dedb4979dcc3';
  const CUSTOM_BUNDLES = { '6e813a3edd180fe07ca4e438849b67b5.bundle': true, '2aa55d46c4def6847148e4e9af03de6d.bundle': true };
  const PICKAXE_ASSET_SLUGS = { star_wand: 'star-wand', fncs: 'fncs-champion', candy_axe: 'candy-axe', minecraft_sword: 'minecraft-sword', leviathan_axe: 'leviathan-axe' };
  const WOOD_LOOKS = [['rainbow', 'Rainbow'], ['natural', 'Natural wood'], ['charcoal', 'Charcoal'], ['whitewash', 'Whitewash / Snow'], ['gold', 'Gold leaf'], ['checker', 'Checker'], ['blue', 'Blue']];
  const ALL_WOOD_LOOKS = WOOD_LOOKS.map(function (e) { return e[0]; });
  const SCOPE_CONFIG = {
    default: { pickaxes: ['star_wand'], woodLooks: ['rainbow', 'natural'] },
    all: { pickaxes: ['star_wand', 'fncs', 'candy_axe', 'minecraft_sword', 'leviathan_axe'], woodLooks: ALL_WOOD_LOOKS },
    builds: { pickaxes: [], woodLooks: ALL_WOOD_LOOKS },
    pickaxes: { pickaxes: ['star_wand', 'fncs', 'candy_axe', 'minecraft_sword', 'leviathan_axe'], woodLooks: [] },
    sweat: { pickaxes: ['star_wand'], woodLooks: ['rainbow', 'natural', 'charcoal', 'whitewash'] },
    vip: { pickaxes: ['star_wand', 'fncs', 'candy_axe', 'minecraft_sword', 'leviathan_axe'], woodLooks: ['rainbow', 'natural', 'gold', 'charcoal'] }
  };

  function selectedScope() {
    try {
      const requested = typeof GM_getValue === 'function' ? String(GM_getValue('cosmeticScope', 'default')).trim().toLowerCase() : 'default';
      return SCOPE_CONFIG[requested] ? requested : 'default';
    } catch (e) { return 'default'; }
  }

  function effectiveScope() {
    return apiScope && SCOPE_CONFIG[apiScope] ? apiScope : selectedScope();
  }

  let dataPromise = null;
  let dataBlobUrl = null;

  function ensureDataBlob() {
    if (dataPromise) return dataPromise;
    const dataUrl = LOCAL + '/files/cosmetics/wood/' + encodeURIComponent(selectedWoodLook()) + '/' + DATA_HASH + '.data?' + STAMP + '&scope=' + encodeURIComponent(effectiveScope());
    dataPromise = gmGet(dataUrl, 180000).then(function (r) {
      dataBlobUrl = makeBlobUrl(r.response, 'application/octet-stream');
      stats.dataBytes = r.response.byteLength;
      return dataBlobUrl;
    }).catch(function (e) {
      dataPromise = null;
      log('DATA FETCH FAILED', e && e.message);
      return null;
    });
    return dataPromise;
  }

  function dataFor(u) {
    if (typeof u !== 'string' || u.indexOf('blob:') === 0) return null;
    const s = u.split('?')[0];
    if (s.indexOf(DATA_HASH) < 0 || !dataBlobUrl) return null;
    if (s.slice(-3) === '.br' || s.slice(-3) === '.gz') return null;
    return dataBlobUrl;
  }

  function setStreamingAssets(root) {
    try {
      const v = W.config;
      if (v && v.unityConfig) v.unityConfig.streamingAssetsUrl = root;
      if (v && v.loaderOptions && v.loaderOptions.unityConfigOptions) v.loaderOptions.unityConfigOptions.streamingAssetsUrl = root;
    } catch (e) {}
  }

  function applyStreamingRoot() {
    const root = origSS || (W.config && W.config.unityConfig && W.config.unityConfig.streamingAssetsUrl);
    if (typeof root === 'string' && root) setStreamingAssets(root);
  }

  function clearUnityCache() {
    if (!IS_GAME_FRAME || !assetsReady || !W.indexedDB || typeof W.indexedDB.databases !== 'function') return Promise.resolve(0);
    return W.indexedDB.databases().then(function (dbs) {
      const names = dbs.map(function (d) { return d.name; }).filter(function (n) { return typeof n === 'string' && /^UnityCache(?:$|[-_])/i.test(n); });
      return Promise.all(names.map(function (n) { return W.indexedDB.deleteDatabase(n); })).then(function () { return names.length; });
    });
  }

  function clearUnityCacheForVersion() {
    if (!IS_GAME_FRAME || !assetsReady) return Promise.resolve(0);
    let cachedVersion;
    try {
      cachedVersion = W.localStorage && W.localStorage.getItem('bngUnityCacheVersion');
    } catch (error) {
      log('could not read Unity cache version; clearing cache', error && error.message);
      return clearUnityCache();
    }
    if (cachedVersion === SCRIPT_VERSION) return Promise.resolve(0);
    return clearUnityCache().then(function (deleted) {
      try {
        if (!W.localStorage) throw new Error('Browser storage is unavailable.');
        W.localStorage.setItem('bngUnityCacheVersion', SCRIPT_VERSION);
      } catch (error) {
        log('could not save Unity cache version', error && error.message);
      }
      return deleted;
    });
  }

  function prefetch() {
    if (!IS_GAME_FRAME) return Promise.resolve(null);
    if (savedLicenseKey()) return prefetchAuthorizedAssets();
    return openLicenseKeyModal().then(function (key) {
      if (!key) throw new Error('No Zeta license key was entered.');
      return prefetchAuthorizedAssets();
    });
  }

  function prefetchAuthorizedAssets() {
    return gmGet(LOCAL + '/cosmetics').then(function (r) {
      const account = JSON.parse(new (W.TextDecoder || TextDecoder)('utf-8').decode(new Uint8Array(r.response)));
      if (!account || !SCOPE_CONFIG[account.scope] || !account.cosmetics) throw new Error('Invalid entitlement response.');
      apiScope = account.scope;
      apiCosmetics = account.cosmetics;
      return Promise.all([
        gmGet(LOCAL_AA + '/settings.json'),
        gmGet(LOCAL_AA + '/catalog.json')
      ]);
    }).then(function (responses) {
      register('settings.json', makeBlobUrl(responses[0].response, 'application/json;charset=utf-8'));
      const cat = JSON.parse(new (W.TextDecoder || TextDecoder)('utf-8').decode(new Uint8Array(responses[1].response)));
      const catalogBytes = new (W.TextEncoder || TextEncoder)().encode(JSON.stringify(cat));
      register('catalog.json', makeBlobUrl(catalogBytes, 'application/json;charset=utf-8'));
      assetsReady = true;

      const scope = effectiveScope();
      const customBundleIds = (cat.m_InternalIds || []).filter(function (id) {
        if (typeof id !== 'string' || id.indexOf(RT_TOKEN) !== 0 ||
            SCOPE_CONFIG[scope].pickaxes.length === 0) return false;
        const filename = id.slice(RT_TOKEN.length).split('?')[0].split('/').pop();
        return CUSTOM_BUNDLES[filename] === true;
      });
      const tasks = customBundleIds.map(function (id) {
        const rel = id.slice(RT_TOKEN.length).split('?')[0];
        const filename = rel.split('/').pop();
        const slug = PICKAXE_ASSET_SLUGS[SCOPE_CONFIG[scope].pickaxes[0]];
        const url = LOCAL + '/files/cosmetics/pickaxes/' + encodeURIComponent(slug) +
          '/' + encodeURIComponent(filename) + '?' + STAMP;
        return gmGet(url).then(function (bundle) {
          register(rel, makeBlobUrl(bundle.response, 'application/octet-stream'));
        }).catch(function () {});
      });
      if (SCOPE_CONFIG[scope].woodLooks.length > 0) tasks.push(ensureDataBlob());
      return Promise.all(tasks);
    });
  }

  function scopeAllowsWood(look) {
    return SCOPE_CONFIG[effectiveScope()].woodLooks.indexOf(look) >= 0;
  }

  function selectedWoodLook() {
    try {
      const stored = W.localStorage && W.localStorage.getItem('bngWoodLook');
      if (stored && scopeAllowsWood(stored)) return stored;
    } catch (e) {
      log('could not read saved wood look', e && e.message);
    }
    const allowed = SCOPE_CONFIG[effectiveScope()].woodLooks;
    return allowed.indexOf('natural') >= 0 ? 'natural' : (allowed[0] || 'natural');
  }

  // ------------------------------------------------------------------ F8 wood picker
  function openWoodPicker() {
    const d = W.document;
    if (!IS_GAME_FRAME || !d) return;
    const existing = d.getElementById('bng-wood-picker');
    if (existing) return;

    function mount() {
      if (!d.body) {
        d.addEventListener('DOMContentLoaded', mount, { once: true });
        return;
      }

      const style = d.createElement('style');
      style.id = 'bng-wood-picker-style';
      style.textContent =
        '@keyframes zeta-wood-in{from{opacity:0;transform:translateY(8px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}' +
        '@keyframes zeta-wood-out{to{opacity:0;transform:translateY(5px) scale(.99)}}' +
        '#bng-wood-picker{position:fixed;inset:0;z-index:2147483647;display:grid;place-items:center;overflow:hidden;padding:16px;background:rgba(0,0,0,.74);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif;color:#f4f4f4;opacity:1;transition:opacity .18s ease}' +
        '#bng-wood-picker.zeta-closing{opacity:0}' +
        '#bng-wood-picker *{box-sizing:border-box}' +
        '#bng-wood-picker .zeta-wood-card{width:min(420px,calc(100vw - 32px));max-height:calc(100vh - 32px);overflow:hidden;padding:22px;border:1px solid #303030;border-radius:18px;background:#141414;box-shadow:0 24px 80px rgba(0,0,0,.58);animation:zeta-wood-in .2s ease both}' +
        '#bng-wood-picker.zeta-closing .zeta-wood-card{animation:zeta-wood-out .16s ease both}' +
        '#bng-wood-picker .zeta-wood-title{margin:0;color:#fff;font-size:19px;font-weight:650;letter-spacing:-.03em}' +
        '#bng-wood-picker .zeta-wood-note{margin:6px 0 16px;color:#aaa;font-size:13px}' +
        '#bng-wood-picker .zeta-wood-status{margin:0 0 12px;padding:10px 12px;border:1px solid #343434;border-radius:10px;background:#1b1b1b;color:#d5d5d5;font-size:12px}' +
        '#bng-wood-picker .zeta-wood-info{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}' +
        '#bng-wood-picker .zeta-wood-info div{min-width:0;padding:9px 10px;border:1px solid #2c2c2c;border-radius:9px;background:#181818}' +
        '#bng-wood-picker .zeta-wood-info small{display:block;margin-bottom:2px;color:#888;font-size:10px;font-weight:650;letter-spacing:.08em;text-transform:uppercase}' +
        '#bng-wood-picker .zeta-wood-info strong{display:block;overflow:hidden;color:#f4f4f4;font-size:12px;font-weight:600;text-overflow:ellipsis;white-space:nowrap}' +
        '#bng-wood-picker .zeta-wood-select{width:100%;height:42px;padding:0 12px;border:1px solid #3a3a3a;border-radius:10px;outline:none;background:#0b0b0b;color:#f5f5f5;font:inherit}' +
        '#bng-wood-picker .zeta-wood-select:focus{border-color:#aaa;box-shadow:0 0 0 3px rgba(255,255,255,.08)}' +
        '#bng-wood-picker .zeta-wood-feedback{min-height:19px;margin-top:9px;color:#aaa;font-size:12px}' +
        '#bng-wood-picker .zeta-wood-credits{margin-top:12px;padding-top:11px;border-top:1px solid #303030;color:#888;font-size:11px;line-height:1.6}' +
        '#bng-wood-picker .zeta-wood-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}' +
        '#bng-wood-picker button{height:38px;padding:0 14px;border:1px solid #f2f2f2;border-radius:10px;background:#f2f2f2;color:#111;font:600 13px system-ui,-apple-system,"Segoe UI",sans-serif;cursor:pointer;transition:background .15s,transform .15s}' +
        '#bng-wood-picker button:hover:not(:disabled){background:#d7d7d7}' +
        '#bng-wood-picker button:active{transform:scale(.98)}' +
        '#bng-wood-picker button:disabled{border-color:#3b3b3b;background:#262626;color:#777;cursor:not-allowed}' +
        '#bng-wood-picker .zeta-wood-secondary{border-color:#414141;background:#1c1c1c;color:#eee}' +
        '#bng-wood-picker .zeta-wood-secondary:hover:not(:disabled){background:#292929}' +
        '@media(prefers-reduced-motion:reduce){#bng-wood-picker,#bng-wood-picker .zeta-wood-card{animation:none;transition:none}}';
      d.head.appendChild(style);

      const overlay = d.createElement('div');
      overlay.id = 'bng-wood-picker';
      overlay.setAttribute('role', 'presentation');
      const card = d.createElement('section');
      card.className = 'zeta-wood-card';
      card.setAttribute('role', 'dialog');
      card.setAttribute('aria-modal', 'true');
      card.setAttribute('aria-labelledby', 'zeta-wood-title');

      const title = d.createElement('h2');
      title.id = 'zeta-wood-title';
      title.className = 'zeta-wood-title';
      title.textContent = 'Build wood texture';
      const note = d.createElement('p');
      note.className = 'zeta-wood-note';
      note.textContent = 'Choose an available look. Reload manually to apply your selection.';
      const status = d.createElement('div');
      status.className = 'zeta-wood-status';
      status.setAttribute('role', 'status');
      status.setAttribute('aria-live', 'polite');
      status.textContent = prefetchState === 'ready'
        ? 'Status: authorized assets ready.'
        : (apiScope
          ? (prefetchState === 'error'
            ? 'Status: authorized asset loading failed; using stock assets.'
            : 'Status: key verified; authorized assets are loading.')
          : (savedLicenseKey()
            ? (prefetchState === 'error'
              ? 'Status: key could not be verified; using stock assets.'
              : 'Status: key saved; waiting for authorization.')
            : 'Status: license key not set; using stock assets.'));

      const info = d.createElement('div');
      info.className = 'zeta-wood-info';
      function addInfo(label, value) {
        const item = d.createElement('div');
        const caption = d.createElement('small');
        caption.textContent = label;
        const content = d.createElement('strong');
        content.textContent = value;
        item.appendChild(caption);
        item.appendChild(content);
        info.appendChild(item);
      }
      addInfo('Key', apiScope ? 'Verified' : (savedLicenseKey() ? 'Saved' : 'Not set'));
      addInfo('Scope', effectiveScope() + (apiScope ? ' · verified' : ''));
      addInfo('Version', SCRIPT_VERSION);

      const select = d.createElement('select');
      select.className = 'zeta-wood-select';
      select.setAttribute('aria-label', 'Wood texture');
      const availableLooks = WOOD_LOOKS.filter(function (entry) {
        return scopeAllowsWood(entry[0]);
      });
      availableLooks.forEach(function (entry) {
        const option = d.createElement('option');
        option.value = entry[0];
        option.textContent = entry[1];
        option.selected = entry[0] === selectedWoodLook();
        select.appendChild(option);
      });

      const feedback = d.createElement('div');
      feedback.className = 'zeta-wood-feedback';
      feedback.textContent = availableLooks.length
        ? 'Current: ' + ((WOOD_LOOKS.find(function (entry) {
            return entry[0] === selectedWoodLook();
          }) || availableLooks[0])[1])
        : 'No wood looks are enabled for this scope.';
      const credits = d.createElement('div');
      credits.className = 'zeta-wood-credits';
      credits.textContent = 'Made by numbers (@cis6led) · Lobby background "zeta" by zeta';

      const actions = d.createElement('div');
      actions.className = 'zeta-wood-actions';
      const closeButton = d.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'zeta-wood-secondary';
      closeButton.textContent = 'Close';
      const saveButton = d.createElement('button');
      saveButton.type = 'button';
      saveButton.textContent = 'Save choice';
      saveButton.disabled = availableLooks.length === 0;

      let closing = false;
      function closePicker() {
        if (closing) return;
        closing = true;
        overlay.classList.add('zeta-closing');
        W.setTimeout(function () {
          overlay.remove();
          style.remove();
        }, 180);
      }
      closeButton.addEventListener('click', closePicker);
      overlay.addEventListener('click', function (event) {
        if (event.target === overlay) closePicker();
      });
      overlay.addEventListener('keydown', function (event) {
        if (event.key === 'Escape') {
          event.preventDefault();
          closePicker();
        }
      });
      saveButton.addEventListener('click', function () {
        const look = select.value;
        if (!scopeAllowsWood(look)) {
          feedback.textContent = 'That wood look is not available in your scope.';
          return;
        }
        try {
          if (!W.localStorage) throw new Error('Browser storage is unavailable.');
          W.localStorage.setItem('bngWoodLook', look);
          feedback.textContent = 'Saved. Press Ctrl+R or F5 to apply this choice.';
        } catch (error) {
          feedback.textContent = 'Could not save your choice: ' +
            String(error && error.message || error);
        }
      });

      actions.appendChild(closeButton);
      actions.appendChild(saveButton);
      card.appendChild(title);
      card.appendChild(note);
      card.appendChild(status);
      card.appendChild(info);
      card.appendChild(select);
      card.appendChild(feedback);
      card.appendChild(credits);
      card.appendChild(actions);
      overlay.appendChild(card);
      d.body.appendChild(overlay);
      select.focus();
    }

    mount();
  }

  if (IS_GAME_FRAME) {
    W.addEventListener('keydown', function (event) {
      if (event.code !== 'F8' || event.repeat) return;
      const target = event.target;
      if (target && /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)) return;
      event.preventDefault();
      event.stopPropagation();
      openWoodPicker();
    }, true);
  }

  // ------------------------------------------------------------------ loadGame hook
  let _lgStarted = false;
  function wrappedLoadGame() {
    const args = arguments;
    if (_lgStarted) return;
    _lgStarted = true;

    const startGame = function() {
      try { applyStreamingRoot(); } catch (e) {}
      try {
        const uc = W.config && W.config.unityConfig;
        if (uc && typeof uc.dataUrl === 'string' && dataBlobUrl && uc.dataUrl.indexOf(DATA_HASH) >= 0) uc.dataUrl = dataBlobUrl;
      } catch (e) {}

      try {
        const r = _loadGame.apply(W, args);
        if (r && typeof r.then === 'function') {
          r.then(function () { report('lg-resolved'); }, function (e) { report('lg-rejected', { m: String(e) }); });
        }
      } catch (e) {
        log('loadGame threw an error:', e);
      }
    };

    Promise.resolve(prefetchPromise).then(function () {
      if (!assetsReady) {
        log('prefetch failed; stock assets will load unchanged');
        startGame();
        return;
      }
      return clearUnityCacheForVersion().then(function (n) {
        report('unity-cache-clear', { n: n });
        startGame();
      }).catch(function (e) {
        log('cache clear failed; starting anyway');
        startGame();
      });
    }).catch(function (e) {
      log('prefetch pipeline error; starting stock game', e);
      startGame();
    });
  }

  try {
    const prev = W.loadGame;
    if (typeof prev === 'function') _loadGame = prev;
    Object.defineProperty(W, 'loadGame', {
      configurable: true, enumerable: true,
      get: function () { return _loadGame ? wrappedLoadGame : undefined; },
      set: function (fn) { _loadGame = fn; }
    });
  } catch (e) { log('loadGame hook failed', e); }

  // ------------------------------------------------------------------ createUnityInstance hook
  function wrappedCreateInstance(canvas, cfg) {
    try {
      if (cfg && typeof cfg.cacheControl === 'function') {
        const orig = cfg.cacheControl;
        cfg.cacheControl = function (u) {
          if (typeof u === 'string' && (u.indexOf('blob:') === 0 || u.indexOf(LOCAL) === 0)) return 'no-store';
          return orig.apply(this, arguments);
        };
      }
      if (cfg && typeof cfg.dataUrl === 'string' && cfg.dataUrl.indexOf(DATA_HASH) >= 0) {
        const args = arguments;
        return ensureDataBlob().then(function (blobUrl) {
          if (blobUrl) cfg.dataUrl = blobUrl;
          return _create.apply(W, args);
        });
      }
    } catch (e) {}
    return _create.apply(W, arguments);
  }

  try {
    const prev = W.createUnityInstance;
    if (typeof prev === 'function') _create = prev;
    Object.defineProperty(W, 'createUnityInstance', {
      configurable: true, enumerable: true,
      get: function () { return _create ? wrappedCreateInstance : undefined; },
      set: function (fn) { _create = fn; }
    });
  } catch (e) {}

  // ------------------------------------------------------------------ Inventory Items & Recte
  const localInventoryItems = [
    { scopeId: 'star_wand', id: 'Pickaxe_Star_Wand', name: 'Star Wand', itemClass: 'Pickaxe' },
    { scopeId: 'fncs', id: 'Pickaxe_FNCS', name: 'FNCS Champion', itemClass: 'Pickaxe' },
    { scopeId: 'candy_axe', id: 'Pickaxe_Candy_Axe', name: 'Candy Axe', itemClass: 'Pickaxe' },
    { scopeId: 'minecraft_sword', id: 'Pickaxe_Minecraft_Diamond_Sword', name: 'Minecraft Diamond Sword', itemClass: 'Pickaxe' },
    { scopeId: 'leviathan_axe', id: 'Pickaxe_Leviathan_Axe', name: 'Leviathan Axe', itemClass: 'Pickaxe' }
  ];

  function grantedInventoryItems() {
    if (!apiScope || !apiCosmetics || !Array.isArray(apiCosmetics.pickaxes)) return [];
    return localInventoryItems.filter(function (item) {
      return SCOPE_CONFIG[effectiveScope()].pickaxes.indexOf(item.scopeId) >= 0 &&
             apiCosmetics.pickaxes.indexOf(PICKAXE_ASSET_SLUGS[item.scopeId]) >= 0;
    });
  }

  function patchInventoryObject(response) {
    const inventory = response && response.data && response.data.InfoResultPayload && response.data.InfoResultPayload.UserInventory;
    if (!Array.isArray(inventory)) return;
    grantedInventoryItems().forEach(function (item) {
      if (inventory.some(function (e) { return e && e.ItemId === item.id; })) return;
      const template = inventory.find(function (e) { return e && e.ItemClass === item.itemClass; });
      if (template) {
        inventory.push(Object.assign({}, template, {
          ItemId: item.id, ItemInstanceId: 'bng-local-' + item.id, ItemClass: item.itemClass, DisplayName: item.name, UnitPrice: 0
        }));
      }
    });
  }

  function isLoginInventoryRequest(input) {
    const url = typeof input === 'string' ? input : (input && typeof input.url === 'string' ? input.url : '');
    return /\/client\/loginwithcustomid(?:[?#]|$)/i.test(url);
  }

  // Recte Catalog Config
  const RECTE_CATALOG_URL = 'https://8415a.playfabapi.com/Client/GetCatalogItems?sdk=UnitySDK-2.206.241122&engine=2022.3.62f2&platform=WebGLPlayer';
  const RECTE_CATALOGS = ['Player', 'Backpack', 'Pickaxe', 'EventOrFree', 'INAPP'];

  function recteCreateItem(item_id, item_class) {
    return { ItemId: item_id, ItemInstanceId: 'A87030AFDB36A4E4', ItemClass: item_class, PurchaseDate: '2025-03-05T23:45:33.867Z', RemainingUses: 1, CatalogVersion: 'EventOrFree', DisplayName: item_id, UnitPrice: 0 };
  }

  function applyRecteUnlock(json, nativeFetch) {
    if (!json || !json.data) return Promise.resolve(null);
    const inv = json.data.InfoResultPayload && json.data.InfoResultPayload.UserInventory;
    if (!Array.isArray(inv)) return Promise.resolve(null); // Not a login payload

    const ticket = json.data.SessionTicket;
    if (!ticket) {
      json.data.InfoResultPayload.UserInventory = [];
      return Promise.resolve(json);
    }

    const cs = new Set(), bp = new Set(), pk = new Set();
    const chains = RECTE_CATALOGS.map(function(ver) {
      return nativeFetch(RECTE_CATALOG_URL, {
        method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Authorization': ticket },
        body: JSON.stringify({ CatalogVersion: ver, AuthenticationContext: null })
      }).then(function(res) { return res.json(); }).then(function(j) {
        ((j && j.data && j.data.Catalog) || []).forEach(function(item) {
          if (item.ItemClass === 'Player') cs.add(item.ItemId);
          else if (item.ItemClass === 'Backpack') bp.add(item.ItemId);
          else if (item.ItemClass === 'Pickaxe') pk.add(item.ItemId);
        });
      }).catch(function() {});
    });

    return Promise.all(chains).then(function() {
      const newInv = [];
      bp.forEach(function(b) { newInv.push(recteCreateItem(b, 'Backpack')); });
      pk.forEach(function(p) { newInv.push(recteCreateItem(p, 'Pickaxe')); });
      cs.forEach(function(c) { newInv.push(recteCreateItem(c, 'Player')); });
      json.data.InfoResultPayload.UserInventory = newInv;
      return json;
    }).catch(function() { return null; });
  }

  // ------------------------------------------------------------------ XHR hook
  if (W.XMLHttpRequest && W.XMLHttpRequest.prototype) {
    const xhrPrototype = W.XMLHttpRequest.prototype;
    const inventoryRequests = new WeakSet();

    function wrapXhrResponseGetter(property) {
      const descriptor = Object.getOwnPropertyDescriptor(xhrPrototype, property);
      if (!descriptor || typeof descriptor.get !== 'function' || !descriptor.configurable) return;
      try {
        Object.defineProperty(xhrPrototype, property, {
          configurable: true, enumerable: descriptor.enumerable,
          get: function () {
            const response = descriptor.get.call(this);
            if (!inventoryRequests.has(this) || this.readyState !== 4) return response;
            if (typeof response === 'string') {
              try { const j = JSON.parse(response); patchInventoryObject(j); return JSON.stringify(j); } catch(e) { return response; }
            }
            if (property === 'response' && response && typeof response === 'object') patchInventoryObject(response);
            return response;
          }
        });
      } catch (e) {}
    }
    wrapXhrResponseGetter('responseText');
    wrapXhrResponseGetter('response');

    const _open = xhrPrototype.open;
    xhrPrototype.open = function (method, url) {
      if (isLoginInventoryRequest(String(url))) inventoryRequests.add(this);
      else inventoryRequests.delete(this);

      try {
        const b = blobFor(url) || dataFor(url);
        if (b) { stats.rewrites++; url = b; }
      } catch (e) {}
      return _open.apply(this, [method, url].concat([].slice.call(arguments, 2)));
    };
  }

  // ------------------------------------------------------------------ fetch hook
  if (W.fetch) {
    const _fetch = W.fetch;
    const nativeFetch = _fetch.bind(W);

    W.fetch = function (input, init) {
      const isLoginRequest = isLoginInventoryRequest(input);
      try {
        if (typeof input === 'string') {
          const b = blobFor(input) || dataFor(input);
          if (b) { stats.rewrites++; input = b; }
        } else if (input && input.url) {
          const b = blobFor(input.url) || dataFor(input.url);
          if (b) { stats.rewrites++; input = new (W.Request || Request)(b, input); }
        }
      } catch (e) {}

      const result = _fetch.call(this, input, init);
      if (!isLoginRequest) return result;

      return result.then(function (response) {
        if (!response || !response.ok || typeof response.clone !== 'function') return response;

        return response.clone().text().then(function (text) {
          let json;
          try { json = JSON.parse(text); } catch (e) { return response; }

          // 1. Run Recte unlock (replaces the UserInventory array)
          return applyRecteUnlock(json, nativeFetch).then(function (replaced) {
            if (!replaced) return response;

            // 2. Append Zeta items to the newly unlocked array
            patchInventoryObject(replaced);

            const out = JSON.stringify(replaced);
            const headers = new (W.Headers || Headers)(response.headers);
            ['content-length', 'content-encoding', 'content-md5', 'etag'].forEach(function (n) { headers.delete(n); });
            return new (W.Response || Response)(out, { status: response.status, statusText: response.statusText, headers: headers });
          });
        }).catch(function (e) {
          log('login response patch failed', e && e.message);
          return response;
        });
      });
    };
  }

  // ------------------------------------------------------------------ start prefetch
  prefetchPromise = prefetch().then(function (result) {
    prefetchState = 'ready';
    return result;
  }).catch(function (error) {
    prefetchState = 'error';
    log('ZETA asset prefetch failed; the stock game will continue:', error.message);
    return null;
  });

  log('v' + SCRIPT_VERSION + ' armed on', location.href, '| API', LOCAL, '| stamp', STAMP);
})();